'use strict';
const SITE='https://ariana-s.vercel.app';
const products=[
{id:'samsa',name:'Самса',category:'piece',tag:'ПО ОДНОЙ ШТУЧКЕ',unit:'шт.',image:'samsa-photo',description:'Румяная выпечка к обеду, чаю и хорошему разговору.'},
{id:'pies',name:'Домашний пирог',category:'pie',tag:'К ОБЩЕМУ СТОЛУ',unit:'пирог',image:'pie',description:'Начинку и размер обсудим под вашу компанию.'},
{id:'sweet',name:'Выпечка к чаю',category:'piece',tag:'МАЛЕНЬКАЯ РАДОСТЬ',unit:'шт.',image:'cake-photo',description:'Сладкий повод сделать паузу. Вид выпечки уточняется.'},
{id:'newyear',name:'Новогодний набор',category:'set',tag:'НОВЫЙ ГОД · КОНЦЕПТ',unit:'набор',image:'christmas',description:'Идея подарочной коробки с выпечкой и праздничным настроением.'},
{id:'halloween',name:'Halloween box',category:'set',tag:'ХЭЛЛОУИН · КОНЦЕПТ',unit:'набор',image:'halloween',description:'Осенний набор для тех, кто любит сладкие сюрпризы.'},
{id:'party',name:'К большому столу',category:'set',tag:'ДЛЯ ЗАСТОЛЬЯ · КОНЦЕПТ',unit:'набор',image:'samsa-photo',description:'Идея сытного ассорти для встречи друзей. Количество обсудим.'},
{id:'celebration',name:'Праздничный набор',category:'set',tag:'ВАШ ОСОБЕННЫЙ ДЕНЬ · КОНЦЕПТ',unit:'набор',image:'cake-photo',description:'Подарочная идея к дню рождения или любому тёплому поводу.'}];
const $=s=>document.querySelector(s);const storage={read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}};
let cart={};const savedCart=storage.read('arianas-cart',{});for(const p of products){const n=Number(savedCart?.[p.id]);if(Number.isInteger(n)&&n>0&&n<=99)cart[p.id]=n}
let profile=storage.read('arianas-profile',{});if(!profile||typeof profile!=='object')profile={};let orders=storage.read('arianas-orders',[]);if(!Array.isArray(orders))orders=[];orders=orders.filter(o=>o&&typeof o.text==='string'&&typeof o.id==='string').slice(0,30);let reviews=storage.read('arianas-reviews',[]);if(!Array.isArray(reviews))reviews=[];reviews=reviews.filter(r=>r&&typeof r.name==='string'&&typeof r.body==='string'&&Number.isInteger(r.rating)&&r.rating>=1&&r.rating<=5).slice(0,10);
let currentFilter='all';let activeOrder=null;let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function open(id){const dialog=document.getElementById(id);if(!dialog)return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(id==='cart'){editOrder();renderCart();prefill();$('#orderDate').min=today()}if(id==='account'){renderAccount();switchTab('profile')}if(id==='review')$('#reviewName').value=typeof profile.name==='string'?profile.name:'';dialog.showModal();document.body.classList.add('modal-open')}
for(const b of document.querySelectorAll('[data-open]'))b.onclick=()=>open(b.dataset.open);for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>b.closest('dialog').close();for(const d of document.querySelectorAll('dialog')){d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open')});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}
function renderProducts(){const query=$('#search').value.trim().toLocaleLowerCase('ru');const result=products.filter(p=>(currentFilter==='all'||p.category===currentFilter)&&`${p.name} ${p.description} ${p.tag}`.toLocaleLowerCase('ru').includes(query));$('#products').replaceChildren();if(!result.length){const p=document.createElement('p');p.className='no-results';p.textContent='Пока не нашли. Попробуйте «самса», «набор» или «пирог».';$('#products').append(p)}for(const p of result){const article=document.createElement('article');article.className='product card';article.dataset.product=p.id;const picture=p.image==='pie'?'<img src="/assets/bakery.webp" alt="Иллюстративное фото пирога, не реальный товар" loading="lazy">':`<div class="atlas ${p.image}" role="img" aria-label="AI-иллюстрация выпечки, не реальный товар"></div>`;article.innerHTML=`<div class="product-picture">${picture}<span class="product-label">${p.category==='set'?'Коллекция · концепт':'На заказ · пример'}</span></div><div class="product-info"><span class="product-meta">${p.tag}</span><h3>${p.name}</h3><p>${p.description}</p><div class="product-bottom"><div>По запросу<small>за ${p.unit==='шт.'?'1 шт.':p.unit==='пирог'?'1 пирог':'1 набор'}</small></div><button class="add" aria-label="Добавить: ${p.name}">+</button></div></div>`;article.querySelector('button').onclick=()=>add(p.id);$('#products').append(article)}}
function add(id){if((cart[id]||0)>=99){toast('Для большого заказа укажите количество в пожеланиях.');return}cart[id]=(cart[id]||0)+1;activeOrder=null;updateCount();toast(`${products.find(p=>p.id===id).name} в корзине`)}
function updateCount(){const count=Object.values(cart).reduce((a,b)=>a+b,0);$('#count').textContent=count;$('#dockCount').textContent=count;storage.write('arianas-cart',cart)}
function renderCart(){const items=products.filter(p=>cart[p.id]);$('#cartItems').replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='empty';empty.innerHTML='Коробка ждёт вкусного.<small>Добавьте выпечку поштучно или выберите праздничный набор.</small><button class="button outline" style="margin-top:22px">Посмотреть меню ↗</button>';empty.querySelector('button').onclick=()=>{$('#cart').close();location.hash='catalog'};$('#cartItems').append(empty);$('#checkout').hidden=true;return}$('#checkout').hidden=false;for(const p of items){const row=document.createElement('div');row.className='cart-row';row.innerHTML=`<div><strong>${p.name}</strong><small>${p.unit} · стоимость уточняется</small></div><div class="qty"><button aria-label="Убрать одну: ${p.name}">−</button><span>${cart[p.id]}</span><button aria-label="Добавить одну: ${p.name}">+</button></div>`;const buttons=row.querySelectorAll('button');buttons[0].onclick=()=>change(p.id,-1);buttons[1].onclick=()=>change(p.id,1);$('#cartItems').append(row)}$('#quantitySummary').textContent=`${Object.values(cart).reduce((a,b)=>a+b,0)} ед. · ${items.length} поз.`}
function change(id,n){const value=(cart[id]||0)+n;if(value>99)return;if(value<=0)delete cart[id];else cart[id]=value;activeOrder=null;updateCount();renderCart()}
function today(){const d=new Date;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function prefill(){if(!$('#orderName').value.trim()&&typeof profile.name==='string')$('#orderName').value=profile.name;if(!$('#orderContact').value.trim()&&typeof profile.contact==='string')$('#orderContact').value=profile.contact}
function editOrder(){$('#orderResult').hidden=true;$('.cart-layout').hidden=false;renderCart()}
$('#editOrder').onclick=editOrder;
$('#checkout').onsubmit=e=>{e.preventDefault();const name=$('#orderName').value.trim(),contact=$('#orderContact').value.trim(),date=$('#orderDate').value;if(!Object.keys(cart).length)return;if(!name||!contact){toast('Укажите имя и контакт.');return}if(date<today()){toast('Выберите сегодняшнюю или будущую дату.');return}const text=['Здравствуйте, Ариана! Хочу обсудить заказ:','',...products.filter(p=>cart[p.id]).map(p=>`${p.name}: ${cart[p.id]} ${p.unit}`),'',`Желаемая дата: ${date.split('-').reverse().join('.')}`,`Получение: ${$('#fulfilment').value}`,`Имя: ${name}`,`Связь: ${contact}`,`Пожелания: ${$('#orderNotes').value.trim()||'обсудим лично'}`,'','Подскажите, пожалуйста, состав, наличие, стоимость и условия получения.'].join('\n');const id=activeOrder||`AR-${Date.now().toString(36).toUpperCase()}`;activeOrder=id;const record={id,text,name,date,created:new Date().toISOString(),quantity:Object.values(cart).reduce((a,b)=>a+b,0)};orders=[record,...orders.filter(o=>o.id!==id)].slice(0,30);const persisted=storage.write('arianas-orders',orders);$('#orderText').value=text;$('#telegramOrder').href=`https://t.me/share/url?url=${encodeURIComponent(SITE)}&text=${encodeURIComponent(text)}`;$('.cart-layout').hidden=true;$('#orderResult').hidden=false;renderAccount();if(!persisted)toast('Браузер запретил сохранение. Скопируйте текст заявки.')};
$('#copyOrder').onclick=async()=>{try{await navigator.clipboard.writeText($('#orderText').value);toast('Текст скопирован. Можно отправить Ариане лично.')}catch{$('#orderText').focus();$('#orderText').select();toast('Выделили текст. Выберите «Копировать».')}};
$('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;currentFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',String(n===b))});renderProducts()};$('#search').oninput=renderProducts;
for(const b of document.querySelectorAll('[data-select]'))b.onclick=()=>{const id=b.dataset.select;add(id);open('cart')};$('#maps').onclick=()=>open('map');$('#shareTg').href=`https://t.me/share/url?url=${encodeURIComponent(SITE)}&text=${encodeURIComponent('Ariana’s - маленькая пекарня для больших поводов')}`;$('#shareVk').href=`https://vk.com/share.php?url=${encodeURIComponent(SITE)}`;
function switchTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#profile').hidden=tab!=='profile';$('#history').hidden=tab!=='orders'}for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>switchTab(b.dataset.tab);
function renderAccount(){const name=typeof profile.name==='string'?profile.name:'';$('#profileName').value=name;$('#profileContact').value=typeof profile.contact==='string'?profile.contact:'';$('#greeting').textContent=name?`Привет, ${name}!`:'Рады вам!';$('#avatar').textContent=name?name[0].toUpperCase():'A';$('#ordersCount').textContent=orders.length;$('#history').replaceChildren();if(!orders.length){const empty=document.createElement('p');empty.className='subnote';empty.textContent='Здесь появятся ваши черновики. Выберите выпечку и нажмите «Подготовить заказ».';$('#history').append(empty)}for(const o of orders){const article=document.createElement('article');article.className='history-card';const title=document.createElement('strong');title.textContent=o.id;const status=document.createElement('small');status.textContent='ЧЕРНОВИК · НЕ ОТПРАВЛЕН';const p=document.createElement('p');p.textContent=`К ${String(o.date||'').split('-').reverse().join('.')} · ${Number(o.quantity)||0} ед.`;const button=document.createElement('button');button.className='text-btn';button.textContent='Открыть текст заявки ↗';button.onclick=()=>{open('cart');$('.cart-layout').hidden=true;$('#orderResult').hidden=false;$('#orderText').value=o.text;$('#telegramOrder').href=`https://t.me/share/url?url=${encodeURIComponent(SITE)}&text=${encodeURIComponent(o.text)}`};article.append(title,status,p,button);$('#history').append(article)}}
$('#profile').onsubmit=e=>{e.preventDefault();const name=$('#profileName').value.trim(),contact=$('#profileContact').value.trim();if(!name||!contact){toast('Укажите имя и контакт.');return}profile={name,contact};const saved=storage.write('arianas-profile',profile);$('#orderName').value=name;$('#orderContact').value=contact;renderAccount();toast(saved?'Профиль сохранён на этом устройстве.':'Профиль заполнен. Браузер запретил сохранение.')};
function appendReview(r){const article=document.createElement('article');article.className='review card';article.dataset.localReview='true';const tag=document.createElement('div');tag.className='review-tag';tag.textContent='ВАШ ОТЗЫВ · ТОЛЬКО НА ЭТОМ УСТРОЙСТВЕ';const stars=document.createElement('span');stars.className='stars';stars.textContent='★'.repeat(r.rating)+'☆'.repeat(5-r.rating);const quote=document.createElement('blockquote');quote.textContent=r.body;const person=document.createElement('div');person.className='review-person';const avatar=document.createElement('span');avatar.textContent=r.name[0].toUpperCase();const name=document.createElement('div');name.textContent=r.name;person.append(avatar,name);article.append(tag,stars,quote,person);$('#reviewList').append(article)}
$('#reviewForm').onsubmit=e=>{e.preventDefault();const name=$('#reviewName').value.trim(),body=$('#reviewBody').value.trim(),rating=Number($('#reviewRating').value);if(!name||!body){toast('Добавьте имя и текст отзыва.');return}const r={name,body,rating};reviews=[...reviews,r].slice(-10);storage.write('arianas-reviews',reviews);document.querySelectorAll('[data-local-review]').forEach(n=>n.remove());reviews.forEach(appendReview);$('#review').close();$('#reviewForm').reset();toast('Отзыв добавлен на вашем устройстве.')};
$('#mobileMenu').onclick=()=>{const hidden=!$('#mobileNav').hidden;$('#mobileNav').hidden=hidden;$('#mobileMenu').setAttribute('aria-expanded',String(!hidden))};$('#mobileNav').addEventListener('click',e=>{if(e.target.closest('a,button')){$('#mobileNav').hidden=true;$('#mobileMenu').setAttribute('aria-expanded','false')}});$('#backTop').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});window.addEventListener('scroll',()=>$('#backTop').classList.toggle('visible',scrollY>500),{passive:true});renderProducts();updateCount();renderAccount();reviews.forEach(appendReview);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

// Reveal sections as they enter the viewport; content remains visible without JS.
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.remove('pending');entry.target.classList.add('visible');observer.unobserve(entry.target)}}},{threshold:.07,rootMargin:'0px 0px 30px 0px'});document.querySelectorAll('.section .reveal').forEach(el=>{el.classList.add('pending');observer.observe(el)})}
